-- Module 15: CRM profiles backed by POS customer and sales history.
insert into public.permissions(key,domain,action,description)values('crm.read','crm','read','View customer profiles and history'),('crm.manage','crm','manage','Manage customers, notes, tags, and segments')on conflict(key)do update set domain=excluded.domain,action=excluded.action,description=excluded.description;
create function private.install_crm_permissions(requested_organization_id uuid)returns void language plpgsql security definer set search_path='' as $$begin insert into public.role_permissions(role_id,permission_id)select role.id,permission.id from public.roles role cross join public.permissions permission where role.organization_id=requested_organization_id and role.key in('owner','administrator','manager','staff')and permission.key='crm.read'on conflict do nothing;insert into public.role_permissions(role_id,permission_id)select role.id,permission.id from public.roles role cross join public.permissions permission where role.organization_id=requested_organization_id and role.key in('owner','administrator','manager')and permission.key='crm.manage'on conflict do nothing;end;$$;
create function private.handle_main_branch_crm_permissions()returns trigger language plpgsql security definer set search_path='' as $$begin if new.code='main'then perform private.install_crm_permissions(new.organization_id);end if;return new;end;$$;create trigger zzzzzzzz_install_crm_permissions_on_main_branch after insert on public.branches for each row execute function private.handle_main_branch_crm_permissions();select private.install_crm_permissions(id)from public.organizations;

alter table public.sales_customers add column address jsonb not null default'{}'check(jsonb_typeof(address)='object'),add column birthdate date,add column company text check(char_length(company)<=160),add column customer_type text not null default'retail'check(customer_type in('retail','wholesale','corporate','vip','other')),add column tags text[]not null default'{}',add column notes text check(char_length(notes)<=2000),add column branch_id uuid,add column visit_count integer not null default 0 check(visit_count>=0),add column outstanding_balance numeric(16,4)not null default 0 check(outstanding_balance>=0);
update public.sales_customers customer set branch_id=(select branch.id from public.branches branch where branch.organization_id=customer.organization_id order by(branch.code='main')desc,branch.created_at limit 1)where branch_id is null;
alter table public.sales_customers alter column branch_id set not null,add foreign key(branch_id,organization_id)references public.branches(id,organization_id)on delete restrict;
create unique index sales_customers_mobile_unique on public.sales_customers(organization_id,phone)where phone is not null;create index sales_customers_branch_name_idx on public.sales_customers(organization_id,branch_id,lower(name));create index sales_customers_tags_idx on public.sales_customers using gin(tags);

create table public.customer_notes(id uuid primary key default gen_random_uuid(),organization_id uuid not null,customer_id uuid not null,note text not null check(char_length(btrim(note))between 1 and 2000),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(customer_id,organization_id)references public.sales_customers(id,organization_id)on delete cascade);
create index customer_notes_customer_idx on public.customer_notes(customer_id,created_at desc);
create table public.customer_segments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,key text not null check(key~'^[a-z][a-z0-9_]{0,63}$'),name text not null check(char_length(btrim(name))between 1 and 120),description text check(char_length(description)<=500),criteria jsonb not null default'[]'check(jsonb_typeof(criteria)='array'),is_active boolean not null default true,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,key));
create table public.customer_loyalty_activity(id uuid primary key default gen_random_uuid(),organization_id uuid not null,customer_id uuid not null,activity_type text not null check(activity_type in('earn','redeem','adjust','expire')),points_delta integer not null check(points_delta<>0),description text check(char_length(description)<=500),reference_type text,reference_id uuid,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(customer_id,organization_id)references public.sales_customers(id,organization_id)on delete cascade);
create index customer_loyalty_customer_idx on public.customer_loyalty_activity(customer_id,created_at desc);
create trigger set_updated_at before update on public.customer_segments for each row execute function private.set_updated_at();

create function private.crm_module_enabled(requested_organization_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='crm');$$;
alter table public.customer_notes enable row level security;alter table public.customer_segments enable row level security;alter table public.customer_loyalty_activity enable row level security;
create policy crm_customers_read on public.sales_customers for select to authenticated using((select private.crm_module_enabled(sales_customers.organization_id))and private.can_business_permission(sales_customers.organization_id,'crm.read',sales_customers.branch_id));
create policy customer_notes_read on public.customer_notes for select to authenticated using(exists(select 1 from public.sales_customers customer where customer.id=customer_notes.customer_id and customer.organization_id=customer_notes.organization_id and private.crm_module_enabled(customer_notes.organization_id)and private.can_business_permission(customer_notes.organization_id,'crm.read',customer.branch_id)));
create policy customer_segments_read on public.customer_segments for select to authenticated using((select private.crm_module_enabled(customer_segments.organization_id))and private.can_business_permission(customer_segments.organization_id,'crm.read',null));
create policy customer_loyalty_read on public.customer_loyalty_activity for select to authenticated using(exists(select 1 from public.sales_customers customer where customer.id=customer_loyalty_activity.customer_id and customer.organization_id=customer_loyalty_activity.organization_id and private.crm_module_enabled(customer_loyalty_activity.organization_id)and private.can_business_permission(customer_loyalty_activity.organization_id,'crm.read',customer.branch_id)));
grant select on public.customer_notes,public.customer_segments,public.customer_loyalty_activity to authenticated;

create function private.normalize_ph_mobile(requested_mobile text)returns text language plpgsql immutable set search_path='' as $$declare digits text:=regexp_replace(coalesce(requested_mobile,''),'[^0-9]','','g');begin if digits=''then return null;elsif digits~'^09[0-9]{9}$'then return'+63'||substr(digits,2);elsif digits~'^639[0-9]{9}$'then return'+'||digits;else raise exception'Enter a valid Philippine mobile number such as 0917 123 4567.'using errcode='22023';end if;end;$$;
create or replace function private.save_sales_customer(requested_organization_id uuid,requested_customer_id uuid,requested_name text,requested_phone text,requested_email text)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid:=coalesce(requested_customer_id,gen_random_uuid());customer_branch uuid;normalized_phone text;begin if(select auth.uid())is null or not private.can_business_permission(requested_organization_id,'sales.create',null)then raise exception'Permission denied.'using errcode='42501';end if;select id into customer_branch from public.branches where organization_id=requested_organization_id and is_active order by(code='main')desc,created_at limit 1;normalized_phone:=private.normalize_ph_mobile(requested_phone);if customer_branch is null or char_length(btrim(requested_name))not between 1 and 160 or char_length(coalesce(requested_email,''))>254 then raise exception'Invalid customer.'using errcode='22023';end if;if requested_customer_id is not null and not exists(select 1 from public.sales_customers where id=target_id and organization_id=requested_organization_id)then raise exception'Customer not found.'using errcode='22023';end if;insert into public.sales_customers(id,organization_id,branch_id,name,phone,email)values(target_id,requested_organization_id,customer_branch,btrim(requested_name),normalized_phone,nullif(lower(btrim(requested_email)),''))on conflict(id)do update set name=excluded.name,phone=excluded.phone,email=excluded.email;return target_id;end;$$;
create function private.customer_segment_criteria_valid(requested_criteria jsonb)returns boolean language plpgsql immutable set search_path='' as $$declare criterion jsonb;begin if jsonb_typeof(requested_criteria)<>'array'or jsonb_array_length(requested_criteria)>10 then return false;end if;for criterion in select value from jsonb_array_elements(requested_criteria)loop if criterion-array['metric','operator','value']::text[]<>'{}'::jsonb or not(criterion?&array['metric','operator','value'])or criterion->>'metric'not in('lifetime_sales','transaction_count','average_transaction','days_since_last_purchase','outstanding_balance','visit_count','loyalty_points','customer_type','tag')or criterion->>'operator'not in('equals','greater_than','less_than','contains')then return false;end if;end loop;return true;end;$$;

create function private.install_default_customer_segments(requested_organization_id uuid,requested_actor uuid)returns void language plpgsql security definer set search_path='' as $$begin insert into public.customer_segments(organization_id,key,name,description,criteria,created_by)values(requested_organization_id,'vip','VIP Customers','High lifetime sales','[{"metric":"lifetime_sales","operator":"greater_than","value":50000}]',requested_actor),(requested_organization_id,'active','Active Customers','Purchased within 90 days','[{"metric":"days_since_last_purchase","operator":"less_than","value":91}]',requested_actor),(requested_organization_id,'lapsed','Lapsed Customers','No purchase in over 180 days','[{"metric":"days_since_last_purchase","operator":"greater_than","value":180}]',requested_actor)on conflict(organization_id,key)do nothing;end;$$;
create function private.save_crm_customer(requested_organization_id uuid,requested_customer_id uuid,requested_branch_id uuid,requested_name text,requested_mobile text,requested_email text,requested_address jsonb,requested_birthdate date,requested_company text,requested_customer_type text,requested_tags text[],requested_notes text)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid:=coalesce(requested_customer_id,gen_random_uuid());normalized_mobile text;clean_tags text[];begin
 if(select auth.uid())is null or not private.crm_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'crm.manage',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;normalized_mobile:=private.normalize_ph_mobile(requested_mobile);select coalesce(array_agg(distinct lower(btrim(tag))order by lower(btrim(tag)))filter(where btrim(tag)<>''),'{}')into clean_tags from unnest(coalesce(requested_tags,'{}'))tag;
 if char_length(btrim(requested_name))not between 1 and 160 or normalized_mobile is null or char_length(coalesce(requested_email,''))>254 or(requested_email<>''and requested_email!~*'^[^@\s]+@[^@\s]+\.[^@\s]+$')or jsonb_typeof(requested_address)<>'object'or requested_birthdate>current_date or char_length(coalesce(requested_company,''))>160 or requested_customer_type not in('retail','wholesale','corporate','vip','other')or cardinality(clean_tags)>20 or exists(select 1 from unnest(clean_tags)tag where char_length(tag)>40)or char_length(coalesce(requested_notes,''))>2000 or not exists(select 1 from public.branches where id=requested_branch_id and organization_id=requested_organization_id and is_active)then raise exception'Invalid customer.'using errcode='22023';end if;
 if requested_customer_id is not null and not exists(select 1 from public.sales_customers where id=target_id and organization_id=requested_organization_id)then raise exception'Customer not found.'using errcode='22023';end if;
 insert into public.sales_customers(id,organization_id,branch_id,name,phone,email,address,birthdate,company,customer_type,tags,notes)values(target_id,requested_organization_id,requested_branch_id,btrim(requested_name),normalized_mobile,nullif(lower(btrim(requested_email)),''),requested_address,requested_birthdate,nullif(btrim(requested_company),''),requested_customer_type,clean_tags,nullif(btrim(requested_notes),''))on conflict(id)do update set branch_id=excluded.branch_id,name=excluded.name,phone=excluded.phone,email=excluded.email,address=excluded.address,birthdate=excluded.birthdate,company=excluded.company,customer_type=excluded.customer_type,tags=excluded.tags,notes=excluded.notes;perform private.install_default_customer_segments(requested_organization_id,(select auth.uid()));return target_id;
exception when unique_violation then raise exception'A customer with this mobile number already exists.'using errcode='23505';end;$$;
create function private.add_customer_note(requested_organization_id uuid,requested_customer_id uuid,requested_note text)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid;branch uuid;begin select branch_id into branch from public.sales_customers where id=requested_customer_id and organization_id=requested_organization_id;if(select auth.uid())is null or branch is null or not private.crm_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'crm.manage',branch)then raise exception'Permission denied.'using errcode='42501';end if;if char_length(btrim(requested_note))not between 1 and 2000 then raise exception'Invalid note.'using errcode='22023';end if;insert into public.customer_notes(organization_id,customer_id,note,created_by)values(requested_organization_id,requested_customer_id,btrim(requested_note),(select auth.uid()))returning id into target_id;return target_id;end;$$;
create function private.save_customer_segment(requested_organization_id uuid,requested_segment_id uuid,requested_key text,requested_name text,requested_description text,requested_criteria jsonb,requested_is_active boolean)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid:=coalesce(requested_segment_id,gen_random_uuid());begin if(select auth.uid())is null or not private.crm_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'crm.manage',null)then raise exception'Permission denied.'using errcode='42501';end if;if requested_key!~'^[a-z][a-z0-9_]{0,63}$'or char_length(btrim(requested_name))not between 1 and 120 or char_length(coalesce(requested_description,''))>500 or not private.customer_segment_criteria_valid(requested_criteria)then raise exception'Invalid customer segment.'using errcode='22023';end if;if requested_segment_id is not null and not exists(select 1 from public.customer_segments where id=target_id and organization_id=requested_organization_id)then raise exception'Segment not found.'using errcode='22023';end if;insert into public.customer_segments(id,organization_id,key,name,description,criteria,is_active,created_by)values(target_id,requested_organization_id,requested_key,btrim(requested_name),nullif(btrim(requested_description),''),requested_criteria,requested_is_active,(select auth.uid()))on conflict(id)do update set key=excluded.key,name=excluded.name,description=excluded.description,criteria=excluded.criteria,is_active=excluded.is_active;return target_id;end;$$;
create function private.record_customer_loyalty(requested_organization_id uuid,requested_customer_id uuid,requested_type text,requested_points integer,requested_description text,requested_reference_type text,requested_reference_id uuid)returns uuid language plpgsql security definer set search_path='' as $$declare target_id uuid;branch uuid;begin select branch_id into branch from public.sales_customers where id=requested_customer_id and organization_id=requested_organization_id;if(select auth.uid())is null or branch is null or not private.can_business_permission(requested_organization_id,'crm.manage',branch)then raise exception'Permission denied.'using errcode='42501';end if;if requested_type not in('earn','redeem','adjust','expire')or requested_points=0 or(requested_type in('redeem','expire')and requested_points>0)or(requested_type='earn'and requested_points<0)then raise exception'Invalid loyalty activity.'using errcode='22023';end if;insert into public.customer_loyalty_activity(organization_id,customer_id,activity_type,points_delta,description,reference_type,reference_id,created_by)values(requested_organization_id,requested_customer_id,requested_type,requested_points,nullif(btrim(requested_description),''),requested_reference_type,requested_reference_id,(select auth.uid()))returning id into target_id;return target_id;end;$$;

create function private.track_customer_visit()returns trigger language plpgsql security definer set search_path='' as $$begin if new.customer_id is not null and new.status='completed'and(tg_op='INSERT'or old.status is distinct from'completed')then update public.sales_customers set visit_count=visit_count+1 where id=new.customer_id;end if;return new;end;$$;create trigger track_customer_visit after insert or update of status on public.sales_transactions for each row execute function private.track_customer_visit();

create function public.save_crm_customer(requested_organization_id uuid,requested_customer_id uuid,requested_branch_id uuid,requested_name text,requested_mobile text,requested_email text,requested_address jsonb,requested_birthdate date,requested_company text,requested_customer_type text,requested_tags text[],requested_notes text)returns uuid language sql security definer set search_path='' as $$select private.save_crm_customer(requested_organization_id,requested_customer_id,requested_branch_id,requested_name,requested_mobile,requested_email,requested_address,requested_birthdate,requested_company,requested_customer_type,requested_tags,requested_notes);$$;
create function public.add_customer_note(requested_organization_id uuid,requested_customer_id uuid,requested_note text)returns uuid language sql security definer set search_path='' as $$select private.add_customer_note(requested_organization_id,requested_customer_id,requested_note);$$;
create function public.save_customer_segment(requested_organization_id uuid,requested_segment_id uuid,requested_key text,requested_name text,requested_description text,requested_criteria jsonb,requested_is_active boolean)returns uuid language sql security definer set search_path='' as $$select private.save_customer_segment(requested_organization_id,requested_segment_id,requested_key,requested_name,requested_description,requested_criteria,requested_is_active);$$;
create function public.record_customer_loyalty(requested_organization_id uuid,requested_customer_id uuid,requested_type text,requested_points integer,requested_description text,requested_reference_type text,requested_reference_id uuid)returns uuid language sql security definer set search_path='' as $$select private.record_customer_loyalty(requested_organization_id,requested_customer_id,requested_type,requested_points,requested_description,requested_reference_type,requested_reference_id);$$;
revoke all on function private.install_crm_permissions(uuid),private.handle_main_branch_crm_permissions(),private.crm_module_enabled(uuid),private.normalize_ph_mobile(text),private.customer_segment_criteria_valid(jsonb),private.install_default_customer_segments(uuid,uuid),private.save_crm_customer(uuid,uuid,uuid,text,text,text,jsonb,date,text,text,text[],text),private.add_customer_note(uuid,uuid,text),private.save_customer_segment(uuid,uuid,text,text,text,jsonb,boolean),private.record_customer_loyalty(uuid,uuid,text,integer,text,text,uuid),private.track_customer_visit()from public,anon,authenticated;
grant execute on function private.crm_module_enabled(uuid)to authenticated;
revoke all on function public.save_crm_customer(uuid,uuid,uuid,text,text,text,jsonb,date,text,text,text[],text),public.add_customer_note(uuid,uuid,text),public.save_customer_segment(uuid,uuid,text,text,text,jsonb,boolean),public.record_customer_loyalty(uuid,uuid,text,integer,text,text,uuid)from public,anon;
grant execute on function public.save_crm_customer(uuid,uuid,uuid,text,text,text,jsonb,date,text,text,text[],text),public.add_customer_note(uuid,uuid,text),public.save_customer_segment(uuid,uuid,text,text,text,jsonb,boolean),public.record_customer_loyalty(uuid,uuid,text,integer,text,text,uuid)to authenticated;
